import{_ as e,o as l,c as a,a3 as n}from"./chunks/framework.bvEHUNtb.js";const f=JSON.parse('{"title":"C-02 北斗七星与斗建","description":"从北斗七星、斗柄指向与九星系统，理解月建和古代时间坐标的天文依据。","frontmatter":{"title":"C-02 北斗七星与斗建","description":"从北斗七星、斗柄指向与九星系统，理解月建和古代时间坐标的天文依据。","category":"guide","outline":"deep","aliases":["北斗七星与斗建","北斗七星","斗建"]},"headers":[],"relativePath":"topics/traditional-wisdom/common-knowledge/bei-dou-dou-jian.md","filePath":"topics/traditional-wisdom/common-knowledge/bei-dou-dou-jian.md","lastUpdated":1786982540000}'),s={name:"topics/traditional-wisdom/common-knowledge/bei-dou-dou-jian.md"};function d(i,t,r,o,g,p){return l(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="c-02-·-北斗七星与斗建-天空中的天然时钟" tabindex="-1">C-02 · 北斗七星与斗建：天空中的天然时钟 <a class="header-anchor" href="#c-02-·-北斗七星与斗建-天空中的天然时钟" aria-label="Permalink to &quot;C-02 · 北斗七星与斗建：天空中的天然时钟&quot;">​</a></h1><p><strong>系列：</strong> 中华传统智慧体系 · 通识基础知识库 · 文化通识篇（C系列）· 天文宇宙组<br><strong>版本：</strong> v1.1（2026年8月）<br><strong>前置篇目（必读）：</strong> 09·二十八星宿 / 13·六十甲子 / 14·二十四节气 / C-01·太岁<br><strong>后续篇目：</strong> C-03·三垣体系 / C-04·十二建除</p><hr><h2 id="写在前面-为什么要学北斗" tabindex="-1">写在前面：为什么要学北斗？ <a class="header-anchor" href="#写在前面-为什么要学北斗" aria-label="Permalink to &quot;写在前面：为什么要学北斗？&quot;">​</a></h2><p>&quot;斗转星移&quot;——这四个字，几乎每个中国人都用过。<br> 但大多数人不知道，这句话背后是一套精密的<strong>天然时钟系统</strong>。</p><p>北斗七星，在中华文化中承担三重角色：</p><ul><li><strong>天文角色：</strong> 斗柄定月建，是古代最直观的时间坐标</li><li><strong>哲学角色：</strong> 天帝之车，宇宙秩序的中枢与象征</li><li><strong>修炼角色：</strong> 道家礼斗延寿，本命星信仰的核心</li></ul><p>不懂北斗，读不懂&quot;月建&quot;从何而来；<br> 不懂北斗，无法理解奇门遁甲九星的命名逻辑；<br> 不懂北斗，也读不懂《史记》《淮南子》《道德经》注疏中大量的星象表述。</p><p><strong>本篇目标：</strong><br> 从天文实体出发，厘清北斗七星→九星的完整体系，<br> 区分天文北斗、道家北斗、奇门北斗三套用法，<br> 还原&quot;斗建&quot;作为月令天文依据的完整逻辑。</p><hr><h2 id="一、俯瞰-这一章在整个体系里的位置" tabindex="-1">一、俯瞰：这一章在整个体系里的位置 <a class="header-anchor" href="#一、俯瞰-这一章在整个体系里的位置" aria-label="Permalink to &quot;一、俯瞰：这一章在整个体系里的位置&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>天文观测</span></span>
<span class="line"><span>  └─ 北斗七星（实体星群）</span></span>
<span class="line"><span>       ├─ 斗柄指向（斗建）</span></span>
<span class="line"><span>       │    └─ 定月令 → 定节气 → 定季节</span></span>
<span class="line"><span>       │         ├─ 接续 主干14·二十四节气</span></span>
<span class="line"><span>       │         ├─ 接续 主干15·历法体系</span></span>
<span class="line"><span>       │         └─ 延伸 C-04·十二建除（月建直接来源）</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       └─ 九星体系（七星 + 左辅右弼）</span></span>
<span class="line"><span>            ├─ 奇门遁甲九星 ← 借用命名，独立运作</span></span>
<span class="line"><span>            ├─ 紫微斗数 ← 贪狼等星名直接调用</span></span>
<span class="line"><span>            └─ 道家内丹 ← 礼斗修炼坐标</span></span></code></pre></div><p><strong>本章解决四个核心问题：</strong></p><ol><li>古人为什么用北斗定时间？</li><li>&quot;建&quot;是什么意思？月建怎么来的？</li><li>九星是什么？和北斗七星什么关系？</li><li>奇门九星 vs 天文九星，区别在哪里？</li></ol><h2 id="二、北斗七星-·-基础" tabindex="-1">二、北斗七星 · 基础 <a class="header-anchor" href="#二、北斗七星-·-基础" aria-label="Permalink to &quot;二、北斗七星 · 基础&quot;">​</a></h2><h3 id="_2-1-七星命名" tabindex="-1">2.1 七星命名 <a class="header-anchor" href="#_2-1-七星命名" aria-label="Permalink to &quot;2.1 七星命名&quot;">​</a></h3><p>【原典】《史记·天官书》<br> 【原文】&quot;北斗七星，所谓&#39;旋、玑、玉衡以齐七政&#39;。杓携龙角，衡殷南斗，魁枕参首。&quot;<br> 【版本】西汉·司马迁撰（史记·天官书）</p><p>【原典】《尚书·舜典》<br> 【原文】&quot;在璿璣玉衡，以齊七政。&quot;<br> 【版本】先秦·佚名撰，孔颖达疏本（唐）<br> 【注】七政：日、月、金、木、水、火、土七曜。璿璣玉衡，古代天文观测仪器，亦借指北斗。</p><blockquote><p>⚠️ <strong>引用辨析：</strong>《史记》引作&quot;旋、玑、玉衡&quot;，《尚书》原文作&quot;璿璣玉衡&quot;，两者为同一概念的不同写法，司马迁引述时略作简化，读古籍时注意区分出处。</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">序号</th><th style="text-align:left;">天文名</th><th style="text-align:left;">道家/星命名</th><th style="text-align:left;">位置说明</th></tr></thead><tbody><tr><td style="text-align:left;">第一星</td><td style="text-align:left;">天枢</td><td style="text-align:left;">贪狼</td><td style="text-align:left;">斗口·北斗之首</td></tr><tr><td style="text-align:left;">第二星</td><td style="text-align:left;">天璇</td><td style="text-align:left;">巨门</td><td style="text-align:left;">斗口</td></tr><tr><td style="text-align:left;">第三星</td><td style="text-align:left;">天玑</td><td style="text-align:left;">禄存</td><td style="text-align:left;">斗口</td></tr><tr><td style="text-align:left;">第四星</td><td style="text-align:left;">天权</td><td style="text-align:left;">文曲</td><td style="text-align:left;">斗口</td></tr><tr><td style="text-align:left;">第五星</td><td style="text-align:left;">玉衡</td><td style="text-align:left;">廉贞</td><td style="text-align:left;">斗柄之始</td></tr><tr><td style="text-align:left;">第六星</td><td style="text-align:left;">开阳</td><td style="text-align:left;">武曲</td><td style="text-align:left;">斗柄</td></tr><tr><td style="text-align:left;">第七星</td><td style="text-align:left;">摇光</td><td style="text-align:left;">破军</td><td style="text-align:left;">斗柄之末</td></tr></tbody></table><p>⚠️ <strong>命名说明：</strong></p><ul><li><strong>天枢/天璇/天玑/天权/玉衡/开阳/摇光</strong> → 天文学名称，出自《史记·天官书》《晋书·天文志》</li><li><strong>贪狼/巨门/禄存/文曲/廉贞/武曲/破军</strong> → 星命/道家体系名称，后世广泛使用</li><li>两套命名并行，本篇均收录，使用时注明语境</li></ul><h3 id="_2-2-斗魁与斗柄" tabindex="-1">2.2 斗魁与斗柄 <a class="header-anchor" href="#_2-2-斗魁与斗柄" aria-label="Permalink to &quot;2.2 斗魁与斗柄&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>斗魁（勺头）：天枢、天璇、天玑、天权 → 四星构成&quot;勺形&quot;</span></span>
<span class="line"><span>斗柄（勺把）：玉衡、开阳、摇光     → 三星延伸为&quot;柄&quot;</span></span></code></pre></div><p><strong>找北极星的方法：</strong><br> 天璇 → 天枢连线，向天枢方向延长约5倍 → 北极星（勾陈一·北辰）<br> 这是古人在没有指南针时确定正北方向的标准方法。</p><blockquote><p>【原典】《晋书·天文志》<br> 【原文】&quot;北斗七星在太微北……魁四星为璇玑，杓三星为玉衡。&quot;<br> 【版本】唐·房玄龄等撰（二十四史标准本）</p></blockquote><p><strong>开阳与辅星（左辅）的天文细节：</strong><br> 开阳（现代天文学名 Mizar）旁有一颗肉眼可见的伴星，称&quot;辅星&quot;（Alcor），<br> 即道家所说的&quot;左辅&quot;。古代常用能否分辨这两颗星来<strong>测试视力</strong>，<br> 是北斗七星中最著名的目视双星组合。</p><p><strong>魁星与科举文化：</strong><br> 斗魁四星（天枢、天璇、天玑、天权）中，天枢为&quot;魁首&quot;，<br> 由此衍生出&quot;魁星点斗、独占鳌头&quot;的科举文化意象——<br> 魁星神信仰，根源正在于北斗斗魁。</p><h2 id="三、斗建-·-月令的天文依据" tabindex="-1">三、斗建 · 月令的天文依据 <a class="header-anchor" href="#三、斗建-·-月令的天文依据" aria-label="Permalink to &quot;三、斗建 · 月令的天文依据&quot;">​</a></h2><h3 id="_3-1-什么是-建" tabindex="-1">3.1 什么是&quot;建&quot;？ <a class="header-anchor" href="#_3-1-什么是-建" aria-label="Permalink to &quot;3.1 什么是&quot;建&quot;？&quot;">​</a></h3><p>&quot;建&quot;，即斗柄所指之方位。</p><p>古人仰观天象，以北斗斗柄在<strong>黄昏时分</strong>的指向，来确定当月的月令（月建）：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>斗柄指向 寅方 → 建寅 → 正月（农历一月）</span></span>
<span class="line"><span>斗柄指向 卯方 → 建卯 → 二月</span></span>
<span class="line"><span>斗柄指向 辰方 → 建辰 → 三月</span></span>
<span class="line"><span>……以此类推，十二月一轮</span></span></code></pre></div><p>【原典】《淮南子·天文训》<br> 【原文】帝张四维，运之以斗，月徙一辰，复返其所。正月指寅，十二月指丑，一岁而匝，终而复始。<br> 【版本】西汉·刘安撰，高诱注本（淮南子·天文训）</p><p>【原典】《礼记·月令》<br> 【原文】&quot;孟春之月，日在营室，昏参中，旦尾中……&quot;<br> 【注】月令以斗建为基础，配合日躔（太阳所在星宿）定月，<br> 是先秦礼制中时间秩序的核心依据。<br> 【版本】先秦·佚名撰，郑玄注本（汉）</p><h3 id="_3-2-十二月建对照表" tabindex="-1">3.2 十二月建对照表 <a class="header-anchor" href="#_3-2-十二月建对照表" aria-label="Permalink to &quot;3.2 十二月建对照表&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">月建</th><th style="text-align:left;">农历月份</th><th style="text-align:left;">节气范围</th><th style="text-align:left;">对应地支</th><th style="text-align:left;">五行</th></tr></thead><tbody><tr><td style="text-align:left;">建寅</td><td style="text-align:left;">正月</td><td style="text-align:left;">立春→惊蛰</td><td style="text-align:left;">寅</td><td style="text-align:left;">木</td></tr><tr><td style="text-align:left;">建卯</td><td style="text-align:left;">二月</td><td style="text-align:left;">惊蛰→清明</td><td style="text-align:left;">卯</td><td style="text-align:left;">木</td></tr><tr><td style="text-align:left;">建辰</td><td style="text-align:left;">三月</td><td style="text-align:left;">清明→立夏</td><td style="text-align:left;">辰</td><td style="text-align:left;">土</td></tr><tr><td style="text-align:left;">建巳</td><td style="text-align:left;">四月</td><td style="text-align:left;">立夏→芒种</td><td style="text-align:left;">巳</td><td style="text-align:left;">火</td></tr><tr><td style="text-align:left;">建午</td><td style="text-align:left;">五月</td><td style="text-align:left;">芒种→小暑</td><td style="text-align:left;">午</td><td style="text-align:left;">火</td></tr><tr><td style="text-align:left;">建未</td><td style="text-align:left;">六月</td><td style="text-align:left;">小暑→立秋</td><td style="text-align:left;">未</td><td style="text-align:left;">土</td></tr><tr><td style="text-align:left;">建申</td><td style="text-align:left;">七月</td><td style="text-align:left;">立秋→白露</td><td style="text-align:left;">申</td><td style="text-align:left;">金</td></tr><tr><td style="text-align:left;">建酉</td><td style="text-align:left;">八月</td><td style="text-align:left;">白露→寒露</td><td style="text-align:left;">酉</td><td style="text-align:left;">金</td></tr><tr><td style="text-align:left;">建戌</td><td style="text-align:left;">九月</td><td style="text-align:left;">寒露→立冬</td><td style="text-align:left;">戌</td><td style="text-align:left;">土</td></tr><tr><td style="text-align:left;">建亥</td><td style="text-align:left;">十月</td><td style="text-align:left;">立冬→大雪</td><td style="text-align:left;">亥</td><td style="text-align:left;">水</td></tr><tr><td style="text-align:left;">建子</td><td style="text-align:left;">十一月</td><td style="text-align:left;">大雪→小寒</td><td style="text-align:left;">子</td><td style="text-align:left;">水</td></tr><tr><td style="text-align:left;">建丑</td><td style="text-align:left;">十二月</td><td style="text-align:left;">小寒→立春</td><td style="text-align:left;">丑</td><td style="text-align:left;">土</td></tr></tbody></table><blockquote><p>⚠️ <strong>月建的起点是节，不是朔日</strong><br> 命理学中，月柱以&quot;节&quot;为界（如立春起寅月），而非农历初一。<br> 这是月建与农历月份的核心区别，读四柱、奇门时务必注意。</p></blockquote><h3 id="_3-3-现代天文解释" tabindex="-1">3.3 现代天文解释 <a class="header-anchor" href="#_3-3-现代天文解释" aria-label="Permalink to &quot;3.3 现代天文解释&quot;">​</a></h3><p>用现代语言重新理解北斗斗建：</p><p>北斗七星，是古人的&quot;天然时钟&quot;。</p><p>地球绕太阳公转，从地面看，北斗斗柄每个月转动约30°，一年转完360°，回到原点。</p><p>古人没有精密仪器，但只要在黄昏时分仰望北方，看斗柄指向哪里，就知道现在是几月。</p><p>这是一套用星象定时间的系统，精确、稳定、不需要任何工具。<br><strong>&quot;建&quot;，就是这根天然指针。</strong></p><h2 id="四、九星体系-·-从七到九" tabindex="-1">四、九星体系 · 从七到九 <a class="header-anchor" href="#四、九星体系-·-从七到九" aria-label="Permalink to &quot;四、九星体系 · 从七到九&quot;">​</a></h2><h3 id="_4-1-为什么是九星" tabindex="-1">4.1 为什么是九星？ <a class="header-anchor" href="#_4-1-为什么是九星" aria-label="Permalink to &quot;4.1 为什么是九星？&quot;">​</a></h3><p>北斗七星之外，道家与星命体系中，另有&quot;左辅&quot;&quot;右弼&quot;二星，合称<strong>北斗九星</strong>。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>北斗七星（可见）：</span></span>
<span class="line"><span>  天枢·天璇·天玑·天权·玉衡·开阳·摇光</span></span>
<span class="line"><span></span></span>
<span class="line"><span>+ 左辅（第八星）：开阳旁的伴星，现代天文学称&quot;辅星&quot;（Alcor），肉眼可见</span></span>
<span class="line"><span>+ 右弼（第九星）：道家认为此星&quot;隐而不显&quot;，各派说法不一</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 北斗九星</span></span></code></pre></div><p>【原典】《太上玄灵北斗本命延生真经》（道教经典）<br> 【原文】&quot;北斗九皇，上应九气，下镇九州……左辅右弼，隐显之间，主掌生死，延寿消灾。&quot;<br> 【版本】道藏本，成书年代约唐宋之间</p><p>⚠️ <strong>左辅右弼的存疑与考证：</strong></p><ul><li><strong>左辅星</strong>（开阳旁辅星/Alcor）：天文学上确实存在，是开阳的目视伴星，肉眼可见，古代亦用于测试视力。</li><li><strong>右弼星</strong>的天文对应，历代说法不一： <ul><li>一说为摇光旁的暗星</li><li>道家内丹体系认为右弼&quot;隐曜&quot;，属于&quot;隐而不见之星&quot;，象征修炼中的<strong>内敛之德</strong>，非天文实体，而是象征性存在</li><li>本篇以&quot;存疑&quot;态度呈现，不以定论方式处理</li></ul></li></ul><h3 id="_4-2-九星命名对照-三套体系" tabindex="-1">4.2 九星命名对照（三套体系） <a class="header-anchor" href="#_4-2-九星命名对照-三套体系" aria-label="Permalink to &quot;4.2 九星命名对照（三套体系）&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">序号</th><th style="text-align:left;">天文名</th><th style="text-align:left;">道家/星命名</th><th style="text-align:left;">奇门遁甲名</th><th style="text-align:left;">五行属性</th></tr></thead><tbody><tr><td style="text-align:left;">第一星</td><td style="text-align:left;">天枢</td><td style="text-align:left;">贪狼</td><td style="text-align:left;">天蓬星</td><td style="text-align:left;">水</td></tr><tr><td style="text-align:left;">第二星</td><td style="text-align:left;">天璇</td><td style="text-align:left;">巨门</td><td style="text-align:left;">天芮星</td><td style="text-align:left;">土</td></tr><tr><td style="text-align:left;">第三星</td><td style="text-align:left;">天玑</td><td style="text-align:left;">禄存</td><td style="text-align:left;">天冲星</td><td style="text-align:left;">木</td></tr><tr><td style="text-align:left;">第四星</td><td style="text-align:left;">天权</td><td style="text-align:left;">文曲</td><td style="text-align:left;">天辅星</td><td style="text-align:left;">木</td></tr><tr><td style="text-align:left;">第五星</td><td style="text-align:left;">玉衡</td><td style="text-align:left;">廉贞</td><td style="text-align:left;">天禽星</td><td style="text-align:left;">土</td></tr><tr><td style="text-align:left;">第六星</td><td style="text-align:left;">开阳</td><td style="text-align:left;">武曲</td><td style="text-align:left;">天心星</td><td style="text-align:left;">金</td></tr><tr><td style="text-align:left;">第七星</td><td style="text-align:left;">摇光</td><td style="text-align:left;">破军</td><td style="text-align:left;">天柱星</td><td style="text-align:left;">金</td></tr><tr><td style="text-align:left;">第八星</td><td style="text-align:left;">左辅</td><td style="text-align:left;">左辅</td><td style="text-align:left;">天任星</td><td style="text-align:left;">土</td></tr><tr><td style="text-align:left;">第九星</td><td style="text-align:left;">右弼</td><td style="text-align:left;">右弼</td><td style="text-align:left;">天英星</td><td style="text-align:left;">火</td></tr></tbody></table><p>⚠️ <strong>三套命名说明：</strong></p><ul><li><strong>天文名</strong>（天枢等）：天文观测用，《史记·天官书》《晋书·天文志》体系</li><li><strong>道家/星命名</strong>（贪狼等）：紫微斗数、风水、道家内丹广泛使用</li><li><strong>奇门遁甲名</strong>（天蓬等）：奇门专用，与前两套有对应关系但功能独立</li></ul><p>⚠️ <strong>天禽星的特殊说明：</strong><br> 天禽星在奇门体系中<strong>居中宫（五宫）</strong>，并非固定运转于某一宫位，<br> 与其他八星的运转逻辑不同。其对应北斗第五星（玉衡/廉贞）为常见说法，<br> 但各家奇门流派在细节上略有出入，学习时注意所用流派的具体定义。</p><h2 id="五、奇门九星-vs-天文九星-·-关键区分" tabindex="-1">五、奇门九星 vs 天文九星 · 关键区分 <a class="header-anchor" href="#五、奇门九星-vs-天文九星-·-关键区分" aria-label="Permalink to &quot;五、奇门九星 vs 天文九星 · 关键区分&quot;">​</a></h2><p>这是学习者<strong>最容易混淆</strong>的地方，必须清晰区分。</p><h3 id="_5-1-天文九星-本体" tabindex="-1">5.1 天文九星（本体） <a class="header-anchor" href="#_5-1-天文九星-本体" aria-label="Permalink to &quot;5.1 天文九星（本体）&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>定义</strong></td><td style="text-align:left;">北斗七星 + 左辅右弼，共九颗实体星（或象征星）</td></tr><tr><td style="text-align:left;"><strong>功能</strong></td><td style="text-align:left;">天文观测、斗建月令、道家修炼坐标</td></tr><tr><td style="text-align:left;"><strong>使用场景</strong></td><td style="text-align:left;">天文历法、道家内丹、紫微斗数</td></tr><tr><td style="text-align:left;"><strong>与九宫关系</strong></td><td style="text-align:left;">斗建对应方位，非直接落宫</td></tr></tbody></table><h3 id="_5-2-奇门遁甲九星-应用" tabindex="-1">5.2 奇门遁甲九星（应用） <a class="header-anchor" href="#_5-2-奇门遁甲九星-应用" aria-label="Permalink to &quot;5.2 奇门遁甲九星（应用）&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>定义</strong></td><td style="text-align:left;">奇门遁甲体系中，以北斗九星命名的九个&quot;能量符号&quot;</td></tr><tr><td style="text-align:left;"><strong>功能</strong></td><td style="text-align:left;">落宫布局，代表九种能量状态，与九宫配合使用</td></tr><tr><td style="text-align:left;"><strong>使用场景</strong></td><td style="text-align:left;">奇门遁甲排盘、择时、方位判断</td></tr><tr><td style="text-align:left;"><strong>与九宫关系</strong></td><td style="text-align:left;">直接落入九宫运转，随局而动</td></tr></tbody></table><blockquote><p>⚠️ <strong>重要区分：</strong><br> 奇门九星&quot;借用&quot;了北斗九星的名字，但在奇门体系中，它们是落入九宫的<strong>能量标签</strong>，不是在直接观测天上的北斗。<br><strong>名同，用途不同。</strong></p></blockquote><h3 id="_5-3-对比总结" tabindex="-1">5.3 对比总结 <a class="header-anchor" href="#_5-3-对比总结" aria-label="Permalink to &quot;5.3 对比总结&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">天文北斗九星</th><th style="text-align:left;">奇门遁甲九星</th></tr></thead><tbody><tr><td style="text-align:left;">本质</td><td style="text-align:left;">天文实体（或象征星）</td><td style="text-align:left;">能量符号/标签</td></tr><tr><td style="text-align:left;">来源</td><td style="text-align:left;">天文观测</td><td style="text-align:left;">借用北斗命名</td></tr><tr><td style="text-align:left;">功能</td><td style="text-align:left;">定时间·定方位·道家修炼</td><td style="text-align:left;">奇门排盘·落宫·判断</td></tr><tr><td style="text-align:left;">与九宫关系</td><td style="text-align:left;">斗建对应方位</td><td style="text-align:left;">直接落入九宫运转</td></tr><tr><td style="text-align:left;">使用场景</td><td style="text-align:left;">历法·道家·紫微</td><td style="text-align:left;">奇门遁甲专用</td></tr></tbody></table><h2 id="六、道家视角-·-北斗的特殊地位" tabindex="-1">六、道家视角 · 北斗的特殊地位 <a class="header-anchor" href="#六、道家视角-·-北斗的特殊地位" aria-label="Permalink to &quot;六、道家视角 · 北斗的特殊地位&quot;">​</a></h2><p>道家对北斗的理解，超越了天文观测，进入了修炼与宇宙观的层面。</p><h3 id="_6-1-北斗为-帝车" tabindex="-1">6.1 北斗为&quot;帝车&quot; <a class="header-anchor" href="#_6-1-北斗为-帝车" aria-label="Permalink to &quot;6.1 北斗为&quot;帝车&quot;&quot;">​</a></h3><p>【原典】《史记·天官书》<br> 【原文】&quot;斗为帝车，运于中央，临制四乡，分阴阳，建四时，均五行，移节度，定诸纪，皆系于斗。&quot;<br> 【版本】西汉·司马迁撰（史记·天官书）</p><p><strong>解读：</strong> 北斗是天帝的车驾，运行于天地中央，统领四方，是宇宙秩序的核心调度者——分阴阳、建四时、均五行，一切时间与方位的秩序，皆系于北斗。</p><h3 id="_6-2-北斗主生死" tabindex="-1">6.2 北斗主生死 <a class="header-anchor" href="#_6-2-北斗主生死" aria-label="Permalink to &quot;6.2 北斗主生死&quot;">​</a></h3><p>【原典】《太上玄灵北斗本命延生真经》（道教经典）<br> 【原文】北斗七元君，主司人间生死，延寿消灾……诵持此经，可消灾延寿，度厄解厄。<br> 【版本】道藏本，约唐宋之间成书</p><p>道教有&quot;<strong>南斗注生，北斗注死</strong>&quot;之说：</p><table tabindex="0"><thead><tr><th style="text-align:left;">星群</th><th style="text-align:left;">职司</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>南斗六星</strong></td><td style="text-align:left;">主生</td><td style="text-align:left;">掌人之寿命起点，注生录</td></tr><tr><td style="text-align:left;"><strong>北斗七星</strong></td><td style="text-align:left;">主死</td><td style="text-align:left;">掌人之寿命终结，注死籍</td></tr></tbody></table><p>故道教有<strong>礼斗延寿</strong>之法——向北斗祈祷，请求延长寿命、消解厄运。</p><blockquote><p>⚠️ <strong>文化科普说明：</strong><br> &quot;南斗注生，北斗注死&quot;是道教信仰体系中的说法，<br> 非天文学论断，亦非儒家经典内容。<br> 本篇作为文化背景收录，读古典小说、道教文献时高频出现。<br> 《西游记》《封神演义》等文学作品中大量使用此意象。</p></blockquote><h3 id="_6-3-本命星与礼斗" tabindex="-1">6.3 本命星与礼斗 <a class="header-anchor" href="#_6-3-本命星与礼斗" aria-label="Permalink to &quot;6.3 本命星与礼斗&quot;">​</a></h3><p>道教认为，人出生之年对应北斗九星中的某一星，称为&quot;<strong>本命星</strong>&quot;：</p><table tabindex="0"><thead><tr><th style="text-align:left;">出生年地支</th><th style="text-align:left;">本命星（道家/星命名）</th><th style="text-align:left;">奇门对应</th></tr></thead><tbody><tr><td style="text-align:left;">子年</td><td style="text-align:left;">贪狼星</td><td style="text-align:left;">天蓬</td></tr><tr><td style="text-align:left;">丑年·亥年</td><td style="text-align:left;">巨门星</td><td style="text-align:left;">天芮</td></tr><tr><td style="text-align:left;">寅年·戌年</td><td style="text-align:left;">禄存星</td><td style="text-align:left;">天冲</td></tr><tr><td style="text-align:left;">卯年·酉年</td><td style="text-align:left;">文曲星</td><td style="text-align:left;">天辅</td></tr><tr><td style="text-align:left;">辰年·申年</td><td style="text-align:left;">廉贞星</td><td style="text-align:left;">天禽</td></tr><tr><td style="text-align:left;">巳年·未年</td><td style="text-align:left;">武曲星</td><td style="text-align:left;">天心</td></tr><tr><td style="text-align:left;">午年</td><td style="text-align:left;">破军星</td><td style="text-align:left;">天柱</td></tr></tbody></table><blockquote><p>⚠️ <strong>存疑标注：</strong><br> 本命星的对应方式，各道派说法有出入，以上为《太上玄灵北斗本命延生真经》常见版本之一，非唯一定论。</p><p>左辅右弼的本命对应，各派另有说法，本篇暂不展开。</p></blockquote><h2 id="七、跨体系接口" tabindex="-1">七、跨体系接口 <a class="header-anchor" href="#七、跨体系接口" aria-label="Permalink to &quot;七、跨体系接口&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">体系</th><th style="text-align:left;">北斗的用途</th><th style="text-align:left;">具体说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>天文历法</strong></td><td style="text-align:left;">斗建定月令</td><td style="text-align:left;">斗柄指向定季节，是古代最直观的时间坐标</td></tr><tr><td style="text-align:left;"><strong>奇门遁甲</strong></td><td style="text-align:left;">九星落宫</td><td style="text-align:left;">天蓬等九星为能量符号，借用北斗命名</td></tr><tr><td style="text-align:left;"><strong>紫微斗数</strong></td><td style="text-align:left;">主星命名</td><td style="text-align:left;">贪狼等星名直接使用，为命盘主星</td></tr><tr><td style="text-align:left;"><strong>道家内丹</strong></td><td style="text-align:left;">修炼坐标</td><td style="text-align:left;">北斗为礼斗延寿之核心，本命星信仰</td></tr><tr><td style="text-align:left;"><strong>风水</strong></td><td style="text-align:left;">九星飞泊</td><td style="text-align:left;">九星与洛书九宫配合，飞星风水的基础</td></tr><tr><td style="text-align:left;"><strong>古典文学</strong></td><td style="text-align:left;">意象来源</td><td style="text-align:left;">&quot;斗转星移&quot;&quot;魁星点斗&quot;&quot;南斗注生北斗注死&quot;等</td></tr></tbody></table><h2 id="八、与主干-c系列的连接" tabindex="-1">八、与主干/C系列的连接 <a class="header-anchor" href="#八、与主干-c系列的连接" aria-label="Permalink to &quot;八、与主干/C系列的连接&quot;">​</a></h2><p><strong>接续（前置）：</strong></p><ul><li>← 主干09·二十八星宿（天文坐标系，北斗与二十八宿共同构成古代天文体系）</li><li>← 主干13·六十甲子（干支纪年，月建地支来源）</li><li>← 主干14·二十四节气（斗建是节气的天文依据）</li><li>← C-01·太岁（岁星纪年 vs 斗建月建，两套时间系统的对比）</li><li>← C-03·三垣体系（北斗属紫微垣，三垣的核心）</li></ul><p><strong>延伸（后续）：</strong></p><ul><li>→ C-04·十二建除（月建的直接应用）</li><li>→ Shu·奇门遁甲（九星体系直接调用）</li><li>→ Shu·紫微斗数（贪狼等星名来源）</li></ul><h2 id="九、本章小结" tabindex="-1">九、本章小结 <a class="header-anchor" href="#九、本章小结" aria-label="Permalink to &quot;九、本章小结&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>北斗七星 · 四句话总结：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 天文功能：</span></span>
<span class="line"><span>   斗柄每月转动约30°，一年一周天</span></span>
<span class="line"><span>   黄昏观斗柄指向，即知当月月建</span></span>
<span class="line"><span>   《淮南子·天文训》：&quot;正月指寅，十二月指丑，一岁而匝&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 九星来源：</span></span>
<span class="line"><span>   北斗七星 + 左辅（开阳伴星）+ 右弼（隐曜/象征星）= 九星</span></span>
<span class="line"><span>   三套命名并行：天文名·道家星命名·奇门名</span></span>
<span class="line"><span>   名称相同，体系不同，用途各异</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. 奇门区分：</span></span>
<span class="line"><span>   天文九星 = 实体星（或象征星），用于历法·道家·紫微</span></span>
<span class="line"><span>   奇门九星 = 能量标签，落入九宫运转，奇门专用</span></span>
<span class="line"><span>   名同用途不同，是最常见的混淆点</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4. 道家地位：</span></span>
<span class="line"><span>   北斗为&quot;帝车&quot;，统领宇宙秩序（《史记·天官书》）</span></span>
<span class="line"><span>   南斗注生·北斗注死，礼斗延寿</span></span>
<span class="line"><span>   本命星信仰，是道教与民间信仰的重要交汇点</span></span></code></pre></div><hr><h2 id="引用来源" tabindex="-1">引用来源 <a class="header-anchor" href="#引用来源" aria-label="Permalink to &quot;引用来源&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">编号</th><th style="text-align:left;">来源</th><th style="text-align:left;">核心内容</th></tr></thead><tbody><tr><td style="text-align:left;">1</td><td style="text-align:left;">《史记·天官书》，西汉·司马迁撰</td><td style="text-align:left;">北斗七星命名；&quot;斗为帝车&quot;；&quot;旋、玑、玉衡以齐七政&quot;</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">《尚书·舜典》，先秦佚名撰，孔颖达疏（唐）</td><td style="text-align:left;">&quot;在璿璣玉衡，以齊七政&quot;——七政原典</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;">《晋书·天文志》，唐·房玄龄等撰（二十四史标准本）</td><td style="text-align:left;">北斗斗魁斗柄的天文描述；开阳与辅星的记载</td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;">《淮南子·天文训》，西汉·刘安撰，高诱注本</td><td style="text-align:left;">&quot;正月指寅，十二月指丑，一岁而匝，终而复始&quot;——斗建月令完整系统</td></tr><tr><td style="text-align:left;">5</td><td style="text-align:left;">《礼记·月令》，先秦佚名撰，郑玄注本（汉）</td><td style="text-align:left;">月令以斗建为基础，配合日躔定月——礼制时间秩序的核心依据</td></tr><tr><td style="text-align:left;">6</td><td style="text-align:left;">《太上玄灵北斗本命延生真经》，道藏本，约唐宋之间成书（道藏·正统道藏本）</td><td style="text-align:left;">北斗九皇；左辅右弼；本命星对应；南斗注生北斗注死</td></tr><tr><td style="text-align:left;">7</td><td style="text-align:left;">《奇门遁甲大全》，明·刘伯温传本系统（各家注本）；参考：《御定奇门宝鉴》清·允禄等撰</td><td style="text-align:left;">奇门九星（天蓬等）的落宫逻辑；天禽星居中宫的特殊性</td></tr></tbody></table><hr><p><strong>前置篇：</strong> C-01·太岁<br><strong>后续篇：</strong> C-03·三垣体系 / C-04·十二建除</p>`,94)])])}const y=e(s,[["render",d]]);export{f as __pageData,y as default};
